def gen_safe_prime(size_bits: int, parallel: bool = False, attempts: int = 4) -> int:
    ts_start: float = time.perf_counter()

    p: int = number_theory.random_safe_prime(size_bits, parallel=parallel, attempts_per_worker=attempts)

    ts_end: float = time.perf_counter()
    elapsed_secs: float = ts_end - ts_start

    default_worker_count: int = min(32, (os.cpu_count() or 1) + 4)
    print(
        f'Found "safe" prime ({size_bits} bits) in {elapsed_secs} secs. [parallel={parallel}, attempts={attempts},'
        f' workers={default_worker_count}] -- "Safe" prime (hex.): {hex(p)}\n'
    )

    return p
